`GET /tickets?size=20` works. `GET /tickets` returns `200` with an empty array, and support insist there are plenty of tickets.

```csharp
app.MapGet("/tickets", async (int size, ITicketRepo repo, CancellationToken ct) =>
{
    var page = await repo.PageAsync(size, ct);
    return Results.Ok(page);
});

// repo
public Task<List<Ticket>> PageAsync(int size, CancellationToken ct)
    => _db.Tickets.OrderBy(t => t.OpenedAt).Take(size).ToListAsync(ct);
```

Why is the response empty rather than an error?

solution.code:
function matchRoute(templates, path) {
  const pathParts = path.split('/').filter(function (s) { return s.length > 0; });
  let winner = 'none';
  let bestScore = -1;
  for (const template of templates) {
    const parts = template.split('/').filter(function (s) { return s.length > 0; });
    if (parts.length !== pathParts.length) {
      continue;
    }
    let matches = true;
    let literals = 0;
    for (let i = 0; i < parts.length; i = i + 1) {
      const seg = parts[i];
      const isParam = seg.startsWith('{') && seg.endsWith('}');
      if (isParam) {
        continue;
      }
      literals = literals + 1;
      if (seg !== pathParts[i]) {
        matches = false;
      }
    }
    if (matches && literals > bestScore) {
      bestScore = literals;
      winner = template;
    }
  }
  return winner;
}

