solution.code:
function pipelineTrace(components, shortCircuitAt) {
  let entered = components;
  if (shortCircuitAt !== null) {
    const stop = components.indexOf(shortCircuitAt);
    if (stop >= 0) {
      entered = components.slice(0, stop + 1);
    }
  }
  const trace = [];
  for (const name of entered) {
    trace.push(name + ':in');
  }
  for (let i = entered.length - 1; i >= 0; i = i - 1) {
    trace.push(entered[i] + ':out');
  }
  return trace;
}

