Validation stated explicitly, and an error contract that does not leak.

```csharp
public sealed class CreateTicketRequest
{
    [Required, StringLength(200, MinimumLength = 1)]
    public string Subject { get; init; } = "";

    [Required, StringLength(10_000)]
    public string Body { get; init; } = "";

    [Range(1, 5)]
    public int Priority { get; init; } = 3;
}

// Minimal APIs do NOT run data annotations for you — check explicitly.
app.MapPost("/tickets", async (CreateTicketRequest req, ITicketRepo repo, CancellationToken ct) =>
{
    var errors = Validate(req);
    if (errors.Count > 0)
    {
        return Results.ValidationProblem(errors);   // 400 + errors dictionary
    }

    var created = await repo.CreateAsync(req, ct);
    return Results.Created($"/tickets/{created.Id}", created);
});
```

And the boundary that turns an unexpected failure into a safe response:

```csharp
app.UseExceptionHandler(handler => handler.Run(async context =>
{
    var feature = context.Features.Get<IExceptionHandlerFeature>();
    var correlationId = context.TraceIdentifier;

    logger.LogError(feature?.Error, "unhandled failure {CorrelationId}", correlationId);

    await Results.Problem(
        title: "An unexpected error occurred.",
        statusCode: 500,
        extensions: new Dictionary<string, object?> { ["correlationId"] = correlationId })
        .ExecuteAsync(context);
}));
```

The caller receives a generic message and an id; the log holds the exception. That split is the whole discipline: diagnosable for the operator, opaque to the client.

